const CANCELLATION_PRECEDENCE = [
    "user",
    "parent",
    "runtime",
    "client_disconnected",
];
export function createCancellationCoordinator(inputs, onCancel) {
    const controller = new AbortController();
    let source = null;
    const listeners = [];
    const disposeListeners = () => {
        for (const remove of listeners.splice(0))
            remove();
    };
    const select = (next, reason) => {
        if (source !== null)
            return;
        source = next;
        disposeListeners();
        onCancel(next);
        controller.abort(reason);
    };
    const preAborted = CANCELLATION_PRECEDENCE.find((candidate) => inputs.some((input) => input.source === candidate && input.signal.aborted));
    if (preAborted) {
        const input = inputs.find((entry) => entry.source === preAborted);
        select(preAborted, input?.signal.reason);
    }
    else {
        for (const input of inputs) {
            const listener = () => select(input.source, input.signal.reason);
            input.signal.addEventListener("abort", listener, { once: true });
            listeners.push(() => input.signal.removeEventListener("abort", listener));
        }
    }
    return {
        signal: controller.signal,
        get source() {
            return source;
        },
        stopConsumer() {
            select("consumer_stopped");
        },
        abortProvider(reason) {
            if (!controller.signal.aborted)
                controller.abort(reason);
        },
        dispose() {
            disposeListeners();
        },
    };
}
